import java.util.Arrays;

class Solution {
    private int[] parent;
    private int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    private void union(int i, int j) {
        int r1 = find(i), r2 = find(j);
        if (r1 != r2) parent[r1] = r2;
    }

    public boolean gcdSort(int[] nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        parent = new int[maxVal + 1];
        for (int i = 0; i <= maxVal; i++) parent[i] = i;

        for (int x : nums) {
            int temp = x;
            for (int d = 2; d * d <= temp; d++) {
                if (temp % d == 0) {
                    union(x, d);
                    while (temp % d == 0) temp /= d;
                }
            }
            if (temp > 1) union(x, temp);
        }

        int[] sortedNums = nums.clone();
        Arrays.sort(sortedNums);
        for (int i = 0; i < nums.length; i++) {
            if (find(nums[i]) != find(sortedNums[i])) return false;
        }
        return true;
    }
}

var gcdSort = function(nums) {
  let maxVal = 0;
  for (const x of nums) if (x > maxVal) maxVal = x;
  const parent = Array.from({ length: maxVal + 1 }, (_, i) => i);
  const find = (i) => {
    if (parent[i] === i) return i;
    return parent[i] = find(parent[i]);
  };
  const union = (i, j) => {
    const r1 = find(i), r2 = find(j);
    if (r1 !== r2) parent[r1] = r2;
  };

  for (const x of nums) {
    let temp = x;
    for (let d = 2; d * d <= temp; d++) {
      if (temp % d === 0) {
        union(x, d);
        while (temp % d === 0) temp = Math.floor(temp / d);
      }
    }
    if (temp > 1) union(x, temp);
  }

  const sortedNums = [...nums].sort((a, b) => a - b);
  for (let i = 0; i < nums.length; i++) {
    if (find(nums[i]) !== find(sortedNums[i])) return false;
  }
  return true;
};
